<patterns>

## Core Patterns

### Pattern 1: Format Tokens (Unicode TR35)

date-fns uses Unicode Technical Standard #35 format tokens. These differ from Moment.js.

#### Format Token Reference

```typescript
import { format } from "date-fns";

// Format string constants
const ISO_DATE_FORMAT = "yyyy-MM-dd";
const ISO_DATETIME_FORMAT = "yyyy-MM-dd'T'HH:mm:ss'Z'";
const DISPLAY_DATE_FORMAT = "MMMM d, yyyy";
const DISPLAY_TIME_FORMAT = "h:mm a";
const DISPLAY_DATETIME_FORMAT = "MMMM d, yyyy 'at' h:mm a";

const date = new Date(2026, 0, 15, 14, 30, 0);

// Year
format(date, "yyyy"); // "2026" (4-digit)
format(date, "yy"); // "26" (2-digit)

// Month
format(date, "MMMM"); // "January" (full name)
format(date, "MMM"); // "Jan" (abbreviated)
format(date, "MM"); // "01" (2-digit)
format(date, "M"); // "1" (1 or 2 digit)

// Day
format(date, "dd"); // "15" (2-digit)
format(date, "d"); // "15" (1 or 2 digit)
format(date, "do"); // "15th" (ordinal)

// Day of week
format(date, "EEEE"); // "Thursday" (full)
format(date, "EEE"); // "Thu" (abbreviated)
format(date, "EEEEE"); // "T" (narrow)

// Hour
format(date, "HH"); // "14" (24-hour, 2-digit)
format(date, "H"); // "14" (24-hour)
format(date, "hh"); // "02" (12-hour, 2-digit)
format(date, "h"); // "2" (12-hour)

// Minute and Second
format(date, "mm"); // "30" (minutes)
format(date, "ss"); // "00" (seconds)

// AM/PM
format(date, "a"); // "PM"
format(date, "aaaa"); // "p.m."

// Timezone
format(date, "z"); // "EST" (short)
format(date, "zzzz"); // "Eastern Standard Time" (full)
```

**Why good:** named constants make format strings reusable and discoverable, Unicode tokens are standard across date libraries

---

### Pattern 2: Parsing ISO Strings

Use `parseISO` or `new Date` for ISO 8601 strings. Both are acceptable in many environments.

```typescript
import { parseISO } from "date-fns";

// ✅ Good Example - parseISO for clarity and consistency
const isoDate = parseISO("2026-01-15");
const isoDateTime = parseISO("2026-01-15T14:30:00Z");

// Also acceptable for simple ISO strings
const simpleDate = new Date("2026-01-15T14:30:00Z"); // works in modern browsers

// Always validate parsed dates
function safeParseDateString(dateString: string): Date | null {
  const parsed = new Date(dateString);
  return isNaN(parsed.getTime()) ? null : parsed;
}

// Custom format parsing (for non-ISO strings)
const CUSTOM_DATE_FORMAT = "dd/MM/yyyy";
const customDate = parse("15/01/2026", CUSTOM_DATE_FORMAT, new Date());
```

**Why good:** `new Date(string)` is simpler and works for ISO strings in most modern browsers; `parseISO` provides extra safety on edge cases

```typescript
// ❌ Bad Example - Using Date constructor without validation
const date = new Date("2026-01-15"); // fine for ISO, but risky for other formats
```

**Why bad:** unvalidated date constructors can produce `Invalid Date` silently if format is unexpected

---

### Pattern 3: Timezone Handling with date-fns-tz

Use `formatInTimeZone` for displaying dates in a specific timezone. For manual calculations, compute an offset difference.

```typescript
import { formatInTimeZone } from "date-fns-tz";
import { addHours } from "date-fns";

// Format constant
const DISPLAY_DATETIME_TZ = "MMMM d, yyyy 'at' h:mm a zzzz";

const dateUtc = parseISO("2026-01-15T14:00:00Z");

// ✅ Good Example - formatInTimeZone for display
const nyDisplay = formatInTimeZone(
  dateUtc,
  "America/New_York",
  DISPLAY_DATETIME_TZ
); // "January 15, 2026 at 9:00 AM Eastern Standard Time"

// Manual offset conversion (when only a fixed offset is known)
const offsetHours = -5; // EST
const localDate = addHours(dateUtc, offsetHours);
const localDisplay = format(localDate, DISPLAY_DATETIME_TZ); // loses timezone info
```

**Why good:** `formatInTimeZone` correctly handles DST and timezone abbreviations; manual offset works for simple cases

```typescript
// ❌ Bad Example - No timezone conversion, assuming UTC
format(dateUtc, "MMMM d, yyyy 'at' h:mm a"); // shows 2:00 PM even if user is in NY
```

**Why bad:** displays UTC time instead of user's local time, confusing for most users

---

### Pattern 4: Date Comparisons and Filtering

Use comparison functions for semantic checks and intervals.

```typescript
import {
  isAfter,
  isBefore,
  isEqual,
  isWithinInterval,
  isToday,
  isFuture,
  isPast,
} from "date-fns";

const now = new Date();
const eventDate = parseISO("2026-01-15T14:00:00Z");

// ✅ Good Example - Semantic comparison
const isUpcoming = isAfter(eventDate, now);
const isPastEvent = isBefore(eventDate, now);

// Interval check (relative to current moment)
const next7Days = addDays(now, 7);
const isInNextWeek = isWithinInterval(eventDate, { start: now, end: next7Days });

// Filter events
function getUpcomingEvents(events: Event[], now: Date): Event[] {
  return events.filter((event) => {
    const eventDate = new Date(event.startTime); // using Date constructor
    return isAfter(eventDate, now);
  });
}
```

**Why good:** semantic names make intent clear; interval checks are straightforward

---

### Pattern 5: Computing Duration Between Two Dates

Use `differenceInHours` and `differenceInMinutes` for approximate duration.

```typescript
import {
  differenceInHours,
  differenceInMinutes,
  differenceInDays,
  differenceInWeeks,
} from "date-fns";

const start = parseISO("2026-01-15T14:00:00Z");
const end = parseISO("2026-01-15T16:30:00Z");

// ✅ Good Example - Duration in hours and minutes
const hours = differenceInHours(end, start);
const minutes = differenceInMinutes(end, start) % 60;
const durationString = `${hours} hours ${minutes} minutes`; // "2 hours 30 minutes"

// For longer durations
const days = differenceInDays(end, start);
const weeks = differenceInWeeks(end, start);
```

**Why good:** simple arithmetic gives a human-readable duration; components are clear

---

### Pattern 6: Relative Labels

Use `formatDistanceToNow` for relative time labels like "3 days ago" or "less than a minute".

```typescript
import { formatDistanceToNow, formatDistance } from "date-fns";
import { enUS } from "date-fns/locale";

const futureDate = parseISO("2026-01-18T14:00:00Z"); // 3 days from now

// ✅ Good Example - Relative distance
const relative = formatDistanceToNow(futureDate, { locale: enUS });
// "3 days" (does not include "in" or "ago" by default)

// To get "in 3 days" or "3 days ago"
const relativeWithSuffix = formatDistanceToNow(futureDate, {
  locale: enUS,
  addSuffix: true,
}); // "in 3 days"

// For present events, check if same day
function getRelativeLabel(eventDate: Date): string {
  if (isToday(eventDate)) return "Starting now";
  const suffix = isAfter(eventDate, new Date()) ? "in" : "ago";
  return `Starts ${formatDistanceToNow(eventDate, { addSuffix: false })}`; // "Starts 3 days"
}
```

**Why good:** `formatDistanceToNow` handles most relative needs; `addSuffix` adds "in" or "ago"

</patterns>

